class Solution { fun reformatNumber(number:String):String{val digits=number.filter{it.isDigit()};val groups=mutableListOf<String>();var index=0;while(digits.length-index>4){groups.add(digits.substring(index,index+3));index+=3};val remaining=digits.length-index;if(remaining==4){groups.add(digits.substring(index,index+2));groups.add(digits.substring(index+2))}else groups.add(digits.substring(index));return groups.joinToString("-")} }
